#pragma once
// INV-REWORK-24 (Misha 2026-11-12): debug "x-ray" of gamepad hints, key F8, only with -dbg.
// Draws boxes around ui_gp_* icons and the labels next to them, the icon middle line and the
// lower-case (x-height) middle line of the label (metrics from configs\ui\gp_font_metrics.ltx,
// generated by _build/inv24/font_metrics.py), and dumps rects to $app_data_root$\gamepad\hint_xray*.txt
// for _build/inv24/xray_check.py.
class dlgItem;
class CGameFont;

namespace GpHintXray
{
bool Allowed();
bool Enabled();
void Toggle();
// true if the key was eaten (F8 with -dbg)
bool OnKey(int dik);
// called from CDialogHolder::DoRenderDialogs after the dialogs are drawn
void RenderDialogs(const xr_vector<dlgItem>& dialogs);
// how far (UI units, + = down) the lower-case middle of font f lies below the middle of its glyph cell;
// a label box centred vertically (valCenter) on line Y has its lower-case middle at Y + this value
float XMidBelowCellCenterUi(CGameFont* f);
}
